import React, { createContext, useContext, useReducer, useEffect } from 'react';

const BotContext = createContext();

const initialState = {
  botStatus: 'stopped', // stopped, running, paused, error
  currentFolder: null,
  processedFiles: 0,
  totalFiles: 0,
  logs: [],
  settings: {
    basePath: 'V',
    timeout: 30,
    autoRestart: false,
  },
  realTimeUpdates: {
    currentAction: '',
    progress: 0,
    lastUpdate: null,
  }
};

function botReducer(state, action) {
  switch (action.type) {
    case 'SET_BOT_STATUS':
      return { ...state, botStatus: action.payload };
    
    case 'SET_CURRENT_FOLDER':
      return { ...state, currentFolder: action.payload };
    
    case 'UPDATE_PROGRESS':
      return { 
        ...state, 
        processedFiles: action.payload.processed,
        totalFiles: action.payload.total 
      };
    
    case 'ADD_LOG':
      return { 
        ...state, 
        logs: [...state.logs, { ...action.payload, timestamp: new Date() }] 
      };
    
    case 'UPDATE_SETTINGS':
      return { 
        ...state, 
        settings: { ...state.settings, ...action.payload } 
      };
    
    case 'UPDATE_REAL_TIME':
      return { 
        ...state, 
        realTimeUpdates: { ...state.realTimeUpdates, ...action.payload } 
      };
    
    case 'CLEAR_LOGS':
      return { ...state, logs: [] };
    
    default:
      return state;
  }
}

export function BotProvider({ children }) {
  const [state, dispatch] = useReducer(botReducer, initialState);

  // Simulate real-time updates
  useEffect(() => {
    if (state.botStatus === 'running') {
      const interval = setInterval(() => {
        // Simulate progress updates
        if (state.processedFiles < state.totalFiles) {
          dispatch({
            type: 'UPDATE_REAL_TIME',
            payload: {
              currentAction: 'กำลังประมวลผลไฟล์...',
              progress: Math.min((state.processedFiles / state.totalFiles) * 100, 100),
              lastUpdate: new Date()
            }
          });
        }
      }, 1000);

      return () => clearInterval(interval);
    }
  }, [state.botStatus, state.processedFiles, state.totalFiles]);

  const startBot = async () => {
    try {
      dispatch({ type: 'SET_BOT_STATUS', payload: 'running' });
      dispatch({ type: 'ADD_LOG', payload: { message: 'เริ่มการทำงานของบอท', level: 'info' } });
      
      // Simulate API call
      // const response = await fetch('/api/bot/start', { method: 'POST' });
      
    } catch (error) {
      dispatch({ type: 'SET_BOT_STATUS', payload: 'error' });
      dispatch({ type: 'ADD_LOG', payload: { message: `เกิดข้อผิดพลาด: ${error.message}`, level: 'error' } });
    }
  };

  const stopBot = async () => {
    try {
      dispatch({ type: 'SET_BOT_STATUS', payload: 'stopped' });
      dispatch({ type: 'ADD_LOG', payload: { message: 'หยุดการทำงานของบอท', level: 'info' } });
      
      // Simulate API call
      // const response = await fetch('/api/bot/stop', { method: 'POST' });
      
    } catch (error) {
      dispatch({ type: 'ADD_LOG', payload: { message: `เกิดข้อผิดพลาด: ${error.message}`, level: 'error' } });
    }
  };

  const pauseBot = async () => {
    try {
      dispatch({ type: 'SET_BOT_STATUS', payload: 'paused' });
      dispatch({ type: 'ADD_LOG', payload: { message: 'หยุดการทำงานชั่วคราว', level: 'warning' } });
      
      // Simulate API call
      // const response = await fetch('/api/bot/pause', { method: 'POST' });
      
    } catch (error) {
      dispatch({ type: 'ADD_LOG', payload: { message: `เกิดข้อผิดพลาด: ${error.message}`, level: 'error' } });
    }
  };

  const updateSettings = (newSettings) => {
    dispatch({ type: 'UPDATE_SETTINGS', payload: newSettings });
  };

  const clearLogs = () => {
    dispatch({ type: 'CLEAR_LOGS' });
  };

  const value = {
    ...state,
    startBot,
    stopBot,
    pauseBot,
    updateSettings,
    clearLogs,
  };

  return (
    <BotContext.Provider value={value}>
      {children}
    </BotContext.Provider>
  );
}

export function useBot() {
  const context = useContext(BotContext);
  if (!context) {
    throw new Error('useBot must be used within a BotProvider');
  }
  return context;
}
